#include <algorithm>
#include <atomic>
#include <charconv>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <limits>
#include <memory>
#include <thread>
#include <vector>

struct Node {
    Node* left;
    Node* right;
};

class Tree {
    std::unique_ptr<Node[]> storage_;

    static Node* build(Node*& next, int depth) {
        Node* node = next++;
        if (depth == 0) {
            node->left = nullptr;
            node->right = nullptr;
        } else {
            node->left = build(next, depth - 1);
            node->right = build(next, depth - 1);
        }
        return node;
    }

    static std::uint64_t count(const Node* node) {
        if (node->left == nullptr) {
            return 1;
        }
        return 1 + count(node->left) + count(node->right);
    }

public:
    explicit Tree(int depth)
        : storage_(new Node[(std::size_t{1} << (depth + 1)) - 1]) {
        Node* next = storage_.get();
        build(next, depth);
    }

    std::uint64_t check() const {
        return count(storage_.get());
    }
};

struct Result {
    int depth;
    std::uint64_t iterations;
    std::uint64_t checksum = 0;
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    int n = 0;
    const char* end = argv[1] + std::strlen(argv[1]);
    const auto parsed = std::from_chars(argv[1], end, n);
    if (parsed.ec != std::errc{} || parsed.ptr != end || n < 0 ||
        n >= std::numeric_limits<std::size_t>::digits - 2 || n >= 64) {
        return 1;
    }

    {
        Tree stretch(n + 1);
        std::printf("stretch tree of depth %d\t check: %llu\n",
                    n + 1,
                    static_cast<unsigned long long>(stretch.check()));
    }

    Tree long_lived(n);

    std::vector<Result> results;
    for (int depth = 4; depth <= n; depth += 2) {
        results.push_back(
            {depth, std::uint64_t{1} << (n - depth + 4), 0});
    }

    if (!results.empty()) {
        std::atomic<std::size_t> next_job{0};

        auto worker = [&]() {
            for (;;) {
                const std::size_t index =
                    next_job.fetch_add(1, std::memory_order_relaxed);
                if (index >= results.size()) {
                    return;
                }

                Result& result = results[index];
                std::uint64_t checksum = 0;
                for (std::uint64_t i = 0; i < result.iterations; ++i) {
                    Tree tree(result.depth);
                    checksum += tree.check();
                }
                result.checksum = checksum;
            }
        };

        const unsigned available =
            std::max(1u, std::thread::hardware_concurrency());
        const std::size_t workers =
            std::min<std::size_t>(available, results.size());

        std::vector<std::thread> threads;
        threads.reserve(workers - 1);
        for (std::size_t i = 1; i < workers; ++i) {
            threads.emplace_back(worker);
        }
        worker();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    for (const Result& result : results) {
        std::printf("%llu\t trees of depth %d\t check: %llu\n",
                    static_cast<unsigned long long>(result.iterations),
                    result.depth,
                    static_cast<unsigned long long>(result.checksum));
    }

    std::printf("long lived tree of depth %d\t check: %llu\n",
                n,
                static_cast<unsigned long long>(long_lived.check()));
    return 0;
}

